// Generates TypeScript types and precompiled validators from the JSON Schemas in schemas/.
// The schemas are the source of truth (ADR 0008); never edit the generated files by hand.
//
//   npm run gen:schemas          regenerate
//   npm run gen:schemas -- --check   fail if the generated files are out of date (CI)

import { readFile, writeFile, mkdir } from 'node:fs/promises';
import { createRequire } from 'node:module';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { compile } from 'json-schema-to-typescript';
import prettier from 'prettier';

const root = resolve(dirname(fileURLToPath(import.meta.url)), '..');

// Use the ajv that @tscore/core depends on (the root may hold an older one for ESLint).
const coreRequire = createRequire(join(root, 'packages/core/package.json'));
const Ajv2020 = coreRequire('ajv/dist/2020').default;
const standaloneCode = coreRequire('ajv/dist/standalone').default;
const outDir = join(root, 'packages/core/src/generated');
const check = process.argv.includes('--check');

/** Each schema, the validator function exported for it, and the generated types file. */
const SCHEMAS = [
  {
    file: 'tscore.event_setup.v1.schema.json',
    fn: 'validateEventSetupSchema',
    types: 'event-setup.ts',
  },
  { file: 'tscore.results.v1.schema.json', fn: 'validateResultsSchema', types: 'results.ts' },
  {
    file: 'tscore.import_mapping.v1.schema.json',
    fn: 'validateImportMappingSchema',
    types: 'import-mapping.ts',
  },
];

const BANNER = '// GENERATED by scripts/gen-schemas.mjs from schemas/. Do not edit.\n';

const prettierConfig = {
  ...(await prettier.resolveConfig(join(root, 'package.json'))),
  filepath: 'x.ts',
};
const format = (code, parser = 'typescript') =>
  prettier.format(code, { ...prettierConfig, parser });

const outputs = new Map();

const schemas = await Promise.all(
  SCHEMAS.map(async (s) => ({
    ...s,
    json: JSON.parse(await readFile(join(root, 'schemas', s.file), 'utf8')),
  })),
);

// 1. Types.
for (const s of schemas) {
  const ts = await compile(s.json, s.json.title, {
    bannerComment: BANNER,
    additionalProperties: false,
    unreachableDefinitions: true,
    ignoreMinAndMaxItems: true,
    format: false,
    style: { singleQuote: true },
  });
  outputs.set(s.types, await format(ts));
}

// 2. Validators. Compiled ahead of time so nothing evaluates code at runtime (the renderer's
// CSP forbids it). Formats (uuid, date, date-time) are documentation for consumers; values
// are enforced with `pattern` where it matters, so no format library is needed.
const ajv = new Ajv2020({
  code: { source: true, esm: true },
  allErrors: true,
  strict: true,
  allowUnionTypes: true,
  validateFormats: false,
});
for (const s of schemas) ajv.addSchema(s.json);
const exportsMap = Object.fromEntries(schemas.map((s) => [s.fn, s.json.$id]));
// ajv's string-length helper (counts Unicode code points, as JSON Schema requires) is emitted
// as a CommonJS require even in ESM mode; inline it so the module has no runtime imports.
const UCS2LENGTH = `function ucs2length(str) {
  let length = 0, pos = 0, value;
  while (pos < str.length) {
    length++;
    value = str.charCodeAt(pos++);
    if (value >= 0xd800 && value <= 0xdbff && pos < str.length) {
      value = str.charCodeAt(pos);
      if ((value & 0xfc00) === 0xdc00) pos++;
    }
  }
  return length;
}
`;
let validatorsJs = standaloneCode(ajv, exportsMap);
if (validatorsJs.includes('ajv/dist/runtime/ucs2length')) {
  validatorsJs =
    UCS2LENGTH +
    validatorsJs.replace(/require\("ajv\/dist\/runtime\/ucs2length"\)\.default/g, 'ucs2length');
}
if (/\brequire\(/.test(validatorsJs)) {
  throw new Error('Generated validators need a runtime require(); adjust ajv options.');
}
outputs.set('validators.js', BANNER + '/* eslint-disable */\n// @ts-nocheck\n' + validatorsJs);

const dts = [
  BANNER,
  "import type { ErrorObject } from 'ajv';",
  '',
  'export interface SchemaValidator {',
  '  (data: unknown): boolean;',
  '  errors?: ErrorObject[] | null;',
  '}',
  '',
  ...schemas.map((s) => `export declare const ${s.fn}: SchemaValidator;`),
  '',
].join('\n');
outputs.set('validators.d.ts', await format(dts));

// 3. Write or check.
await mkdir(outDir, { recursive: true });
let stale = [];
for (const [name, content] of outputs) {
  const path = join(outDir, name);
  const current = await readFile(path, 'utf8').catch(() => null);
  if (current === content) continue;
  if (check) stale.push(name);
  else await writeFile(path, content);
}

if (check && stale.length) {
  console.error(
    `Generated schema files are out of date: ${stale.join(', ')}\nRun: npm run gen:schemas`,
  );
  process.exit(1);
}
console.log(
  check ? 'Generated schema files are up to date.' : `Wrote ${outputs.size} files to ${outDir}`,
);
